package com.eynny.npships.block;

import net.minecraft.core.Direction;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

/** Generated by ImportEditorAssets.py: filled cursor profile, separate sparse native collision. */
final class SchematicEditorShape {
    private static final VoxelShape[] OUTLINES = rotations(outlineNorth());
    private static final VoxelShape[] COLLISIONS = rotations(collisionNorth());

    private SchematicEditorShape() {}

    static VoxelShape outline(Direction facing) {
        return OUTLINES[facing.get2DDataValue()];
    }

    static VoxelShape collision(Direction facing) {
        return COLLISIONS[facing.get2DDataValue()];
    }

    private static VoxelShape outlineNorth() {
        return Shapes.or(
                        Shapes.empty(),
                        Block.box(0, 0, 2, 16, 10, 7),
                        Block.box(0, 0, 7, 16, 12, 10),
                        Block.box(0, 0, 10, 16, 13, 14))
                .optimize();
    }

    private static VoxelShape collisionNorth() {
        return Shapes.or(
                        Shapes.empty(),
                        Block.box(0, 0, 2, 2, 1, 14),
                        Block.box(14, 0, 2, 16, 1, 14),
                        Block.box(0.5, 1, 8, 1.5, 8, 10),
                        Block.box(14.5, 1, 8, 15.5, 8, 10),
                        Block.box(0, 8, 7, 2, 11, 10),
                        Block.box(14, 8, 7, 16, 11, 10),
                        Block.box(0, 9, 1.61731657, 16, 10.0823922, 2),
                        Block.box(0, 9, 2, 16, 10.49660576, 3),
                        Block.box(0, 9.41421356, 3, 16, 10.91081933, 4),
                        Block.box(0, 9.82842712, 4, 16, 11.32503289, 5),
                        Block.box(0, 10.24264069, 5, 16, 11.73924645, 6),
                        Block.box(0, 10.65685425, 6, 16, 12.15346001, 7),
                        Block.box(0, 11.07106781, 7, 16, 12.56767357, 8),
                        Block.box(0, 11.48528137, 8, 16, 12.98188714, 9),
                        Block.box(0, 11.89949494, 9, 16, 13.3961007, 10),
                        Block.box(0, 12.3137085, 10, 16, 13.81031426, 11),
                        Block.box(0, 12.72792206, 11, 16, 14.22452782, 12),
                        Block.box(0, 13.14213562, 12, 16, 14.51608072, 13),
                        Block.box(0, 13.55634919, 13, 16, 13.80116197, 13.08655439),
                        Block.box(1, 9, 5.23463314, 15, 11.1647844, 6),
                        Block.box(1, 9, 6, 15, 11.57899796, 7),
                        Block.box(1, 9.41421356, 7, 15, 11.99321153, 8),
                        Block.box(1, 9.82842712, 8, 15, 12.37849279, 9),
                        Block.box(1, 10.24264069, 9, 15, 12.20986303, 9.69551813),
                        Block.box(13, 9, 7, 14, 11, 9),
                        Block.box(2, 9, 7, 3, 11, 9))
                .optimize();
    }

    private static VoxelShape[] rotations(VoxelShape north) {
        var result = new VoxelShape[4];
        var facing = Direction.NORTH;
        var shape = north;
        for (int i = 0; i < 4; i++) {
            result[facing.get2DDataValue()] = shape;
            if (i == 3) break;
            VoxelShape[] rotated = {Shapes.empty()};
            shape.forAllBoxes(
                    (x0, y0, z0, x1, y1, z1) ->
                            rotated[0] =
                                    Shapes.or(
                                            rotated[0],
                                            Shapes.box(1 - z1, y0, x0, 1 - z0, y1, x1)));
            shape = rotated[0].optimize();
            facing = facing.getClockWise();
        }
        return result;
    }
}
